const buttons=[...document.querySelectorAll('[data-filter]')],entries=[...document.querySelectorAll('.entry')],search=document.querySelector('input[type=search]');let selected='all';function update(){const q=search.value.trim().toLocaleLowerCase('uk');let count=0;for(const row of entries){row.hidden=!((selected==='all'||row.dataset.category===selected)&&row.dataset.search.toLocaleLowerCase('uk').includes(q));if(!row.hidden)count++}document.querySelector('.empty').hidden=count!==0;document.querySelector('#result-count').textContent=`${count} із ${entries.length} нотаток`;buttons.forEach(b=>{const active=b.dataset.filter===selected;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});document.querySelector('.listhead h2').textContent=selected==='all'?'Усі нотатки':selected}buttons.forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.filter;update()}));search.addEventListener('input',update);
